\set ON_ERROR_STOP on
do $$ declare
 tenant uuid:='10000000-0000-4000-8000-000000000001';owner uuid:='00000000-0000-4000-8000-000000000001';reviewer uuid:='00000000-0000-4000-8000-000000000002';candidate uuid:='00000000-0000-4000-8000-000000000003';foreign_user uuid:='00000000-0000-4000-8000-000000000004';
 a uuid;b uuid;result jsonb;manifest jsonb;input jsonb;receipt jsonb;ticket jsonb;report jsonb;item uuid;assessment uuid;published uuid;window_id uuid;registration uuid;attempt uuid;definition jsonb;form jsonb;
begin
 input:=jsonb_build_object('filename','Protected image.png','mime','image/png','byte_length',3,'parts',jsonb_build_array(jsonb_build_object('sha256',repeat('a',64),'byte_length',3)));
 result:=assessment_artifact_command(owner,tenant,'artifact-begin-001','upload.begin',input);a:=(result->>'id')::uuid;
 if assessment_artifact_command(owner,tenant,'artifact-begin-001','upload.begin',input)<>result then raise exception 'Upload begin replay differs';end if;
 begin perform assessment_artifact_command(owner,tenant,'artifact-begin-001','upload.begin',jsonb_set(input,'{filename}','"Other.png"'));raise exception 'Manifest identity conflict accepted';exception when unique_violation then null;end;
 begin perform assessment_artifact_command(foreign_user,tenant,'artifact-foreign-001','upload.begin',input);raise exception 'Foreign upload accepted';exception when insufficient_privilege then null;end;
 begin perform assessment_artifact_command(owner,tenant,'artifact-invalid-parts','upload.begin',jsonb_set(input,'{parts,0,byte_length}','2'));raise exception 'Wrong part size accepted';exception when invalid_parameter_value then null;end;
 begin perform assessment_artifact_transport(owner,tenant,'upload.complete',jsonb_build_object('artifact_id',a));raise exception 'Incomplete upload completed';exception when check_violation then null;end;
 begin perform assessment_artifact_transport(owner,tenant,'read.authorize',jsonb_build_object('artifact_id',a));raise exception 'Unscanned content readable';exception when check_violation then null;end;
 receipt:=jsonb_build_object('artifact_id',a,'index',0,'sha256',repeat('a',64),'byte_length',3,'cipher_sha256',repeat('b',64),'iv',repeat('c',24),'key_id','test-k1','object_key','assessment/'||tenant||'/'||a||'/0/'||repeat('a',64),'etag','storage-etag');
 begin perform assessment_artifact_transport(owner,tenant,'chunk.receipt',jsonb_set(receipt,'{sha256}',to_jsonb(repeat('f',64))));raise exception 'Unpinned bytes accepted';exception when unique_violation then null;end;
 begin perform assessment_artifact_transport(owner,tenant,'chunk.receipt',jsonb_set(receipt,'{object_key}','"foreign-object"'));raise exception 'Foreign object accepted';exception when invalid_parameter_value then null;end;
 result:=assessment_artifact_transport(owner,tenant,'chunk.receipt',receipt);
 if assessment_artifact_transport(owner,tenant,'chunk.receipt',receipt)<>result then raise exception 'Part receipt replay differs';end if;
 begin update assessment_artifact_parts set iv=repeat('f',24) where artifact_id=a;raise exception 'Storage receipt mutated';exception when check_violation then null;end;
 result:=assessment_artifact_transport(owner,tenant,'upload.complete',jsonb_build_object('artifact_id',a));manifest:=result;
 if result->>'state'<>'quarantined' or length(result->>'manifest_hash')<>64 then raise exception 'Completion bypassed quarantine';end if;
 if assessment_artifact_transport(owner,tenant,'upload.complete',jsonb_build_object('artifact_id',a))<>result then raise exception 'Completion replay changed';end if;
 if (select count(*) from assessment_artifact_scan_jobs where artifact_id=a)<>1 then raise exception 'Duplicate scan jobs';end if;
 begin perform assessment_artifact_transport(owner,tenant,'read.authorize',jsonb_build_object('artifact_id',a));raise exception 'Quarantine readable';exception when check_violation then null;end;
 ticket:=assessment_artifact_scan_claim(1)->0;
 if ticket->>'artifact_id'<>a::text then raise exception 'Wrong scan claim';end if;
 perform assessment_artifact_scan_bundle((ticket->>'job_id')::uuid,(ticket->>'lease_token')::uuid,true);
 begin perform assessment_artifact_scan_bundle((ticket->>'job_id')::uuid,gen_random_uuid(),false);raise exception 'Forged scan lease readable';exception when unique_violation then null;end;
 report:=jsonb_build_object('job_id',ticket->'job_id','lease_token',ticket->'lease_token','manifest_hash',ticket->'manifest_hash','verdict','clean','detected_mime','image/png','decoder_checked',true,'scanner_id','synthetic-scanner','scanner_version','fixture-1','signature_version','fixture-1','report_hash',repeat('e',64));
 begin perform assessment_artifact_scan_report(jsonb_set(report,'{decoder_checked}','false'));raise exception 'Unchecked decoder accepted';exception when check_violation then null;end;
 begin perform assessment_artifact_scan_report(jsonb_set(report,'{manifest_hash}',to_jsonb(repeat('f',64))));raise exception 'Other manifest accepted';exception when invalid_parameter_value then null;end;
 begin perform assessment_artifact_scan_report(jsonb_set(report,'{detected_mime}','"text/html"'));raise exception 'Wrong detected MIME accepted';exception when check_violation then null;end;
 result:=assessment_artifact_scan_report(report);if result->>'state'<>'ready' then raise exception 'Trusted report not recorded';end if;
 if assessment_artifact_scan_report(report)<>result then raise exception 'Scan acknowledgement replay changed';end if;
 begin perform assessment_artifact_scan_report(jsonb_set(report,'{report_hash}',to_jsonb(repeat('f',64))));raise exception 'Changed report replay accepted';exception when unique_violation then null;end;
 perform assessment_artifact_transport(owner,tenant,'read.authorize',jsonb_build_object('artifact_id',a));
 begin perform assessment_artifact_transport(foreign_user,tenant,'read.authorize',jsonb_build_object('artifact_id',a));raise exception 'Foreign artifact readable';exception when insufficient_privilege then null;end;
 begin update assessment_artifacts set manifest='[]' where id=a;raise exception 'Ready manifest mutable';exception when check_violation then null;end;
 begin update assessment_artifacts set state='uploading' where id=a;raise exception 'Ready artifact regenerated';exception when check_violation then null;end;
 update tenant_memberships set status='inactive' where tenant_id=tenant and user_id=owner;
 begin perform assessment_artifact_command(owner,tenant,'artifact-begin-001','upload.begin',input);raise exception 'Revoked actor replay accepted';exception when insufficient_privilege then null;end;
 update tenant_memberships set status='active' where tenant_id=tenant and user_id=owner;
 if assessment_artifact_read(owner,tenant,null,1)->>'next_cursor' is not null then raise exception 'Unexpected pagination cursor';end if;
 result:=assessment_artifact_command(owner,tenant,'artifact-begin-002','upload.begin',input);b:=(result->>'id')::uuid;
 result:=assessment_artifact_read(owner,tenant,null,1);if jsonb_array_length(result->'items')<>1 or result->>'next_cursor' is null or result::text like '%expected_parts%' or result::text like '%object_key%' then raise exception 'Library projection/pagination leaked storage fields';end if;
 begin perform assessment_command(owner,tenant,'artifact-unready-item','item.create',jsonb_build_object('bank_id',(select id from assessment_item_banks where tenant_id=tenant limit 1),'item',jsonb_build_object('schema_version','assessment.item.v1','type','numeric','prompt','Unready','locale','en','max_score',1,'tags','[]'::jsonb,'media',jsonb_build_array(jsonb_build_object('artifact_id',b,'kind','image','alt','Image'))),'key','{"numeric":{"value":1,"tolerance":0}}'::jsonb));raise exception 'Quarantined/pending media item created';exception when check_violation then null;end;
 perform assessment_artifact_command(owner,tenant,'artifact-cancel-002','upload.cancel',jsonb_build_object('artifact_id',b));
 begin perform assessment_artifact_transport(owner,tenant,'chunk.authorize',jsonb_build_object('artifact_id',b,'index',0));raise exception 'Cancelled upload authorized';exception when check_violation then null;end;
 -- Current-section candidate access uses the actual immutable form, not a caller's item list.
 result:=assessment_command(owner,tenant,'artifact-ready-item','item.create',jsonb_build_object('bank_id',(select id from assessment_item_banks where tenant_id=tenant limit 1),'item',jsonb_build_object('schema_version','assessment.item.v1','type','numeric','prompt','Ready image','locale','en','max_score',1,'tags','[]'::jsonb,'media',jsonb_build_array(jsonb_build_object('artifact_id',a,'kind','image','alt','Reviewed image'))),'key','{"numeric":{"value":1,"tolerance":0}}'::jsonb));item:=(result->>'id')::uuid;
 perform assessment_command(owner,tenant,'artifact-submit-item','item.submit',jsonb_build_object('id',item));perform assessment_command(reviewer,tenant,'artifact-approve-item','item.approve',jsonb_build_object('id',item));
 definition:=jsonb_build_object('schema_version','assessment.definition.v1','title','Protected media delivery','locale','en','duration_seconds',600,'shuffle_items',false,'shuffle_options',false,'sections',jsonb_build_array(jsonb_build_object('id','76000000-0000-4000-8000-000000000001','title','Images','item_version_ids',jsonb_build_array(item),'draw_count',1)));
 result:=assessment_command(owner,tenant,'artifact-create-exam','assessment.create',jsonb_build_object('definition',definition));assessment:=(result->>'id')::uuid;result:=assessment_command(owner,tenant,'artifact-publish-exam','assessment.publish',jsonb_build_object('id',assessment,'revision',1));published:=(result->>'id')::uuid;
 result:=assessment_command(owner,tenant,'artifact-create-window','window.create',jsonb_build_object('assessment_version_id',published,'title','Protected media test','opens_at',clock_timestamp()-interval '1 hour','closes_at',clock_timestamp()+interval '1 hour'));window_id:=(result->>'id')::uuid;
 result:=assessment_command(owner,tenant,'artifact-register','registration.create',jsonb_build_object('window_id',window_id,'candidate_id',candidate));registration:=(result->>'id')::uuid;
 form:=jsonb_build_object('schema_version','assessment.manifest.v1','assessment_version_id',published,'duration_seconds',600,'sections',jsonb_build_array(jsonb_build_object('id','76000000-0000-4000-8000-000000000001','items',jsonb_build_array(jsonb_build_object('item_version_id',item,'item',(select payload from assessment_item_versions where id=item))))));
 result:=pg_temp.assessment_command(candidate,tenant,'artifact-start','attempt.start',jsonb_build_object('registration_id',registration,'manifest',form,'manifest_hash',repeat('f',64)));attempt:=(result->>'id')::uuid;
 perform assessment_artifact_transport(candidate,tenant,'read.authorize',jsonb_build_object('artifact_id',a,'attempt_id',attempt));
 begin perform assessment_artifact_transport(foreign_user,tenant,'read.authorize',jsonb_build_object('artifact_id',a,'attempt_id',attempt));raise exception 'Other candidate media readable';exception when no_data_found then null;end;
 update assessment_attempts set section_index=1 where id=attempt;
 begin perform assessment_artifact_transport(candidate,tenant,'read.authorize',jsonb_build_object('artifact_id',a,'attempt_id',attempt));raise exception 'Old/future section media readable';exception when no_data_found then null;end;
end; $$;
set role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000001',false);
do $$ begin
 begin perform * from assessment_artifact_parts;raise exception 'Raw envelopes readable';exception when insufficient_privilege then null;end;
 begin perform assessment_artifact_scan_claim(1);raise exception 'User scanner RPC callable';exception when insufficient_privilege then null;end;
 begin perform assessment_artifact_transport('00000000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000000001','upload.complete','{}');raise exception 'User storage RPC callable';exception when insufficient_privilege then null;end;
end; $$;
reset role;
